import{_ as t,o as i,c as a,a3 as s}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"ATLAS Automation Exporter / Editor","description":"Analyser et exporter les automatisations Home Assistant avec ATLAS.","frontmatter":{"title":"ATLAS Automation Exporter / Editor","description":"Analyser et exporter les automatisations Home Assistant avec ATLAS."},"headers":[],"relativePath":"fr/projects/atlas-plugins/automation-extractor.md","filePath":"fr/projects/atlas-plugins/automation-extractor.md","lastUpdated":1792857501000}'),o={name:"fr/projects/atlas-plugins/automation-extractor.md"};function r(n,e,l,u,c,d){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="atlas-automation-exporter-editor" tabindex="-1">ATLAS Automation Exporter / Editor <a class="header-anchor" href="#atlas-automation-exporter-editor" aria-label="Permalink to &quot;ATLAS Automation Exporter / Editor&quot;">​</a></h1><p>ATLAS Automation Exporter / Editor est un plugin autonome d’ATLAS. Il reprend l’idée de l’ancien outil Windows de séparation de <code>automations.yaml</code> et l’intègre directement à l’architecture des plugins ATLAS.</p><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><p>Le plugin analyse les automatisations Home Assistant, exporte les éléments sélectionnés et prépare leur modification dans File Studio.</p><h2 id="depot" tabindex="-1">Dépôt <a class="header-anchor" href="#depot" aria-label="Permalink to &quot;Dépôt&quot;">​</a></h2><ul><li>GitHub : <code>https://github.com/rockbaer2007/atlas-automation-exporter-editor-plugin</code></li><li>Page d’installation : <code>https://rockbaer2007.github.io/atlas-automation-exporter-editor-plugin/install.html</code></li><li>Fichier du dépôt : <code>https://raw.githubusercontent.com/rockbaer2007/atlas-automation-exporter-editor-plugin/main/repository.json</code></li><li>Version installable actuelle : <code>0.1.28</code></li><li>Interface en allemand, anglais et français ; la langue ATLAS enregistrée est appliquée à l’ouverture du plugin.</li></ul><p>Dans l’Administration ATLAS, vous pouvez saisir directement l’URL GitHub. Lors de la vérification, ATLAS la convertit automatiquement en adresse <code>repository.json</code> correspondante.</p><p>Depuis 0.1.28, l&#39;analyse compte les véritables éléments YAML des déclencheurs, conditions et actions. Les en-têtes et étapes imbriquées n&#39;ajoutent pas d&#39;éléments principaux. Les syntaxes moderne et classique sont prises en charge. Paramètres et automatisations sources restent inchangés ; une sauvegarde précède toujours l’analyse du fichier système chargé.</p><ul><li>lire <code>/config/automations.yaml</code> via le chemin File Studio autorisé ;</li><li>sauvegarder le contenu chargé de <code>/config/automations.yaml</code> avant son analyse, dans <code>/config/atlas_backups/automations/&lt;date-heure&gt;/automations.yaml</code> ;</li><li>analyser les fichiers <code>.yaml</code> et <code>.yml</code> importés ;</li><li>afficher l’ID, l’alias, la description, les déclencheurs, les conditions et les actions ;</li><li>détecter les appels de service au format classique <code>service:</code> et au format moderne <code>action: domain.service</code> ;</li><li>conserver une automatisation contenant un fragment de déclencheur ou d’action à la racine comme une seule entrée afin d’éviter de faux conflits ;</li><li>conserver les déclencheurs horaires au format <code>HH:MM:SS</code> entre guillemets et convertir les valeurs numériques en secondes, par exemple <code>25200</code> en <code>&#39;07:00:00&#39;</code> ;</li><li>signaler les ID ou alias absents ou en double, les déclencheurs ou actions manquants et les automatisations désactivées ;</li><li>marquer les ID et alias en double comme conflits dans la liste ;</li><li>filtrer les automatisations qui comportent des avertissements ;</li><li>afficher le YAML détaillé avec une coloration similaire à File Studio ;</li><li>limiter la liste à environ 15 lignes visibles et la faire défiler indépendamment ;</li><li>afficher les entités, scripts, scènes, assistants et cibles de notification associés ;</li><li>regrouper et filtrer les automatisations par domaine, zone ou appareil ;</li><li>choisir le dossier d’exportation et enregistrer la sélection dans un dossier horodaté ;</li><li>créer deux fichiers portant le même nom : une version d’exportation avec <code>id</code> et une version d’importation nettoyée sans <code>id</code> pour l’éditeur YAML Home Assistant ;</li><li>consulter les automatisations exportées et préparer leur modification dans File Studio.</li></ul><h2 id="securite" tabindex="-1">Sécurité <a class="header-anchor" href="#securite" aria-label="Permalink to &quot;Sécurité&quot;">​</a></h2><p>Le plugin n’écrit pas dans les fichiers système de Home Assistant. Il lit les fichiers YAML système ou importés, crée une sauvegarde avant d’ouvrir le véritable <code>automations.yaml</code>, analyse les automatisations et exporte des fichiers YAML séparés. La restauration manuelle et la modification ultérieure se font dans File Studio et avec les outils YAML de Home Assistant.</p><h2 id="restauration-securisee-du-plugin" tabindex="-1">Restauration sécurisée du plugin <a class="header-anchor" href="#restauration-securisee-du-plugin" aria-label="Permalink to &quot;Restauration sécurisée du plugin&quot;">​</a></h2><p>Dans <strong>Administration → Gestionnaire de plugins → Automation Exporter / Editor → Restaurer</strong>, choisir une sauvegarde existante. Vérifier version, direction et compatibilité, puis utiliser l’action qui sauvegarde le plugin actuel et applique la version choisie. Annuler conserve l’installation. Une modification simultanée du plugin ou de sa gestion impose un nouvel aperçu.</p><p>Cette opération restaure le <strong>paquet du plugin</strong>. Elle ne rétablit pas un ancien état des automatisations sources, exports, projets, corbeille ou historique. Elle n’importe rien automatiquement dans Home Assistant et n’écrit pas dans <code>automations.yaml</code>.</p><div class="info custom-block"><p class="custom-block-title">Vérification isolée du 16/10/2026</p><p>Les vrais paquets <strong>0.1.27 → 0.1.28 → 0.1.27 → 0.1.28</strong> ont été vérifiés avec ATLAS 0.1.312 : redémarrage, aperçu, annulation et restauration dans l’interface. Un aperçu périmé est refusé après une modification effective de la gestion. Dépôts et données de test isolées ont été sauvegardés avant les changements. YAML source, exports existants, projet, autre plugin, corbeille et historique restent identiques. Analyse DE/EN/FR, sauvegardes identiques à la source, paires d’export/import avec/sans ID et ouverture dans File Studio réussissent. La version HA provient d’un serveur de test local : ni authentification HA réelle, ni mise à jour GitHub, ni migration de format ne sont qualifiées. <strong>Pi 5 et Proxmox sont restés inchangés pendant cet essai isolé.</strong></p></div><div class="info custom-block"><p class="custom-block-title">Vérification native ultérieure sur Pi 5 et Proxmox le 16/10/2026</p><p>Après de nouvelles sauvegardes HA locales et des copies supplémentaires sur PC, les deux hôtes passent <strong>0.1.28 installée → 0.1.27 → 0.1.28 d’origine</strong>. Le vrai ancien paquet est appliqué via l’aperçu de compatibilité du serveur ; annulation et restauration de la nouvelle sauvegarde utilisent l’administration. Les hôtes conservent ATLAS 0.1.312 et HA 2026.10.1.</p><p>Les neuf fichiers du plugin d’origine sont restaurés exactement. Automatisations sources contrôlées, exports et sauvegardes d’automatisations existants, paramètres, projets serveur, autres plugins, corbeille et historique sont conservés. L’analyse d’un YAML de test importé est identique avant et après restauration. Aucune automatisation utilisateur n’est exportée, exécutée ou réécrite dans HA ; aucun redémarrage HA/App n’est nécessaire. Ce contrôle ne qualifie ni restauration HA complète, ni migration de format, ni nouvelle publication GitHub.</p></div><p>Après restauration, recharger l’administration et la page du plugin. Pendant l’essai, l’administration ouverte signalait brièvement des changements non enregistrés alors que l’état serveur était correctement restauré. Le rechargement affichait de nouveau l’état partagé. Ne pas adopter un ancien état local pour cette seule raison.</p><p>Langue et apparence sont enregistrées localement. Analyse chargée, sélection, filtres, dossier d’export saisi et liste des exports appartiennent à la session. Après rechargement, charger de nouveau la source et choisir le dossier si nécessaire. Les fichiers déjà exportés restent disponibles dans File Studio.</p><h2 id="role" tabindex="-1">Rôle <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Rôle&quot;">​</a></h2><p>ATLAS Automation Exporter / Editor complète File Studio : File Studio fournit une interface de fichiers sécurisée, tandis que l’Automation Exporter / Editor analyse et exporte les automatisations.</p>',20)])])}const g=t(o,[["render",r]]);export{m as __pageData,g as default};
